<template><div class="progress-page"><div class="progress-hero"><div><span>我的学习成长</span><h2>自适应练习成果</h2><p>这里只统计你真正提交过题目的自适应练习，与普通试卷成绩分开。</p></div><button class="iq-btn iq-btn-secondary" @click="load" :disabled="loading">刷新成果</button></div><div v-if="loading" class="iq-card empty">正在读取练习成果...</div><template v-else><div class="metrics"><div><b>{{summary.sessionCount||0}}</b><span>有效练习次数</span><small>至少答过1题</small></div><div><b>{{summary.answeredCount||0}}</b><span>累计完成题目</span><small>已提交的题目</small></div><div><b>{{summary.accuracy||0}}%</b><span>总体正确率</span><small>{{summary.correctCount||0}}题答对</small></div><div><b>{{summary.sessionCount?summary.highestDifficulty:'-'}}</b><span>达到的最高难度</span><small>{{summary.sessionCount?difficultyLabel(summary.highestDifficulty):'尚未开始'}}</small></div></div><div v-if="!Number(summary.sessionCount)" class="iq-card empty"><h3>还没有有效练习成果</h3><p>完成并提交至少一道自适应题目后，这里会显示你的正确率、难度变化和知识点表现。</p><button class="iq-btn iq-btn-primary" @click="$emit('practice')">去开始练习</button></div><template v-else><div class="grid"><section class="iq-card card"><h3>五级难度表现</h3><div class="level" v-for="n in 5" :key="n"><span>{{n}}级 · {{difficultyLabel(n)}}</span><div><i :style="{width:`${difficultyItem(n)?.accuracy||0}%`}"></i></div><b>{{difficultyItem(n)?.answeredCount||0}}题 / {{difficultyItem(n)?.accuracy||0}}%</b></div></section><section class="iq-card card"><h3>需要优先巩固的知识点</h3><div v-if="!data.byKnowledge.length" class="mini-empty">暂无知识点数据</div><div class="knowledge" v-for="k in data.byKnowledge" :key="k.knowledgePoint"><div><b>{{k.knowledgePoint}}</b><span>答对{{k.correctCount}}/{{k.answeredCount}}题</span></div><em :class="Number(k.accuracy)>=80?'good':Number(k.accuracy)<=40?'weak':''">{{k.accuracy}}%</em></div></section></div><section class="iq-card history"><div class="title"><h3>我的练习记录</h3><span>最近{{data.sessions.length}}次有效练习</span></div><div class="record" v-for="s in data.sessions" :key="s.id"><div><b>{{rangeText(s)}}</b><span>{{formatTime(s.updated_at)}}</span></div><div><b>完成{{s.answered_count}}/{{s.planned_count}}题</b><span>答对{{s.correct_count}}题 · {{s.accuracy}}%</span></div><div><b>1级 → {{s.current_difficulty}}级</b><span>{{difficultyLabel(s.current_difficulty)}}</span></div><em :class="s.status">{{s.status==='completed'?'按计划完成':`提前结束，还差${Number(s.planned_count)-Number(s.answered_count)}题`}}</em></div></section></template></template></div></template>
<script setup>import{onMounted,ref}from'vue';import{getAdaptiveProgress}from'@/api/practice';const emit=defineEmits(['toast','practice']),loading=ref(false),data=ref({summary:{},sessions:[],byDifficulty:[],byKnowledge:[]}),summary=ref({});const load=async()=>{loading.value=true;try{data.value=await getAdaptiveProgress();summary.value=data.value.summary||{}}catch(e){emit('toast',e.message||'读取成果失败','error')}finally{loading.value=false}};const difficultyLabel=n=>Number(n)<=2?'简单':Number(n)<=4?'中等':'困难',difficultyItem=n=>data.value.byDifficulty.find(x=>Number(x.difficulty)===n),rangeText=s=>`${s.chapters?`第${String(s.chapters).replaceAll(',','、')}章`:'全部章节'} · ${s.knowledge_keyword||'不限知识点'}`,formatTime=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'-';onMounted(load);</script>
<style scoped>.progress-page{display:grid;gap:18px;max-width:1180px;margin:0 auto;width:100%}.progress-hero{display:flex;justify-content:space-between;align-items:center;padding:28px 32px;border-radius:20px;background:linear-gradient(130deg,#075985,#2563eb 58%,#6366f1);color:white;box-shadow:0 15px 40px #2563eb30}.progress-hero h2{font-size:29px;margin:6px 0}.progress-hero p{margin:0;color:#dbeafe}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.metrics>div{display:grid;padding:20px;background:white;border:1px solid #e2e8f0;border-radius:14px}.metrics b{font-size:29px;color:#1e40af}.metrics span{color:#475569}.metrics small{color:#94a3b8}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card,.history{padding:22px}.card h3,.history h3{margin-top:0}.level{display:grid;grid-template-columns:110px 1fr 100px;align-items:center;gap:10px;margin:14px 0}.level>div{height:10px;background:#e2e8f0;border-radius:6px}.level i{display:block;height:100%;background:linear-gradient(90deg,#60a5fa,#4f46e5);border-radius:6px}.level b{text-align:right;font-size:13px}.knowledge{display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-bottom:1px solid #eef2f7}.knowledge div{display:grid}.knowledge span{font-size:12px;color:#64748b}.knowledge em{font-style:normal;padding:5px 9px;border-radius:13px;background:#fef3c7;color:#a16207}.knowledge em.good{background:#dcfce7;color:#15803d}.knowledge em.weak{background:#fee2e2;color:#b91c1c}.title{display:flex;justify-content:space-between}.title span{color:#64748b}.record{display:grid;grid-template-columns:2fr 1fr 1fr 170px;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid #eef2f7}.record div{display:grid}.record span{font-size:12px;color:#64748b}.record em{text-align:center;font-style:normal;padding:5px 8px;border-radius:12px;background:#fef3c7;color:#a16207}.record em.completed{background:#dcfce7;color:#15803d}.empty{padding:50px;text-align:center}.mini-empty{padding:35px;color:#64748b;text-align:center}@media(max-width:850px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.record{grid-template-columns:1fr 1fr}}</style>
